      [("rééducation","On prescrit une rééducation supervisée du plancher pelvien d'au moins 3 mois.","Elle est le traitement de première ligne."),("hygiène de vie","On aide à perdre du poids si l'IMC dépasse 30 kg/m².","La perte de poids réduit la pression sur le plancher."),("geste ou chirurgie","On discute une bandelette rétropubienne ou un agent de comblement après l'échec.","Le geste corrige le soutien urétral.")],
